from pathlib import Path

# PLAY-014 — UI-only parity for GYM/OUTDOOR player.
# No generation, mechanic, prescription or backend selection rules are modified here.

session_path = Path('app/workout/session.js')
session = session_path.read_text(encoding='utf-8')

session = session.replace("import EnvironmentSwapOverlay from '../../src/components/workout/EnvironmentSwapOverlay';\n", '')
session = session.replace(
    "  const canRegeneratePlanB =\n    Boolean(workout?.sessionId) && !isEnvironmentSession && !progressRecorded;",
    "  const canRegeneratePlanB = Boolean(workout?.sessionId) && !progressRecorded;"
)

old_render = '''      {isEnvironmentSession ? (\n        <>\n          <EnvironmentSessionCore environmentCode={environmentCode} />\n          <EnvironmentSwapOverlay />\n        </>\n      ) : (\n        <SessionCore\n          onOpenOverview={() => {\n            setPlanBOpen(false);\n            setOverviewOpen(true);\n          }}\n          onOpenPlanB={() => {\n            if (!canRegeneratePlanB) return;\n            setOverviewOpen(true);\n            setPlanBOpen(true);\n          }}\n          onOpenWhy={() => setWhyOpen(true)}\n          onOpenAdjust={() => setAdaptationOpen(true)}\n          showPlanB={showPlanBEntry}\n        />\n      )}\n\n      {isEnvironmentSession ? (\n        <View style={styles.sessionTools} pointerEvents="box-none">\n          <Pressable\n            onPress={() => setOverviewOpen(true)}\n            style={({ pressed }) => [styles.toolButton, pressed && styles.pressed]}\n          >\n            <Ionicons name="clipboard-outline" size={18} color={colors.text} />\n            <Text style={styles.toolButtonText}>Ma séance</Text>\n          </Pressable>\n        </View>\n      ) : null}\n'''
new_render = '''      {isEnvironmentSession ? (\n        <EnvironmentSessionCore\n          environmentCode={environmentCode}\n          onOpenOverview={() => {\n            setPlanBOpen(false);\n            setOverviewOpen(true);\n          }}\n          onOpenPlanB={() => {\n            if (!canRegeneratePlanB) return;\n            setOverviewOpen(true);\n            setPlanBOpen(true);\n          }}\n          onOpenWhy={() => setWhyOpen(true)}\n          onOpenAdjust={() => setAdaptationOpen(true)}\n          showPlanB={showPlanBEntry}\n        />\n      ) : (\n        <SessionCore\n          onOpenOverview={() => {\n            setPlanBOpen(false);\n            setOverviewOpen(true);\n          }}\n          onOpenPlanB={() => {\n            if (!canRegeneratePlanB) return;\n            setOverviewOpen(true);\n            setPlanBOpen(true);\n          }}\n          onOpenWhy={() => setWhyOpen(true)}\n          onOpenAdjust={() => setAdaptationOpen(true)}\n          showPlanB={showPlanBEntry}\n        />\n      )}\n'''
if old_render not in session:
    raise SystemExit('session render block not found')
session = session.replace(old_render, new_render, 1)

# session.js no longer owns a separate floating environment toolbar.
session = session.replace("import { Alert, Pressable, StyleSheet, Text, View } from 'react-native';", "import { Alert, StyleSheet, View } from 'react-native';")
session = session.replace("import { Ionicons } from '@expo/vector-icons';\n", '')
session = session.replace("import { spacing } from '../../src/constants';\n", '')

old_styles = '''    sessionTools: {\n      position: 'absolute',\n      left: spacing.lg,\n      right: spacing.lg,\n      bottom: 84,\n      zIndex: 32,\n      flexDirection: 'row',\n      justifyContent: 'space-between',\n      pointerEvents: 'box-none',\n    },\n    toolButton: {\n      minHeight: 40,\n      paddingHorizontal: 12,\n      borderRadius: 12,\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surfaceElevated,\n      flexDirection: 'row',\n      alignItems: 'center',\n      justifyContent: 'center',\n      gap: 6,\n      shadowColor: colors.shadow,\n      shadowOpacity: isDark ? 0.24 : 0.08,\n      shadowRadius: 10,\n      shadowOffset: { width: 0, height: 4 },\n    },\n    toolButtonText: {\n      fontFamily: 'Manrope_700Bold',\n      fontSize: 10,\n      color: colors.text,\n    },\n    pressed: { opacity: 0.76 },\n'''
session = session.replace(old_styles, '')
session_path.write_text(session, encoding='utf-8')

# Environment swap: keep the exact backend availability/adaptation rules, but stop floating the action
# over the player and allow generated environment exercises to use backend-approved swaps too.
overlay_path = Path('src/components/workout/EnvironmentSwapOverlay.js')
overlay = overlay_path.read_text(encoding='utf-8')
overlay = overlay.replace('export default function EnvironmentSwapOverlay() {', "export default function EnvironmentSwapOverlay({ variant = 'floating' } = {}) {")
overlay = overlay.replace(
'''  const swapExercise =\n    current &&\n    isManualBuilderBlock &&\n    SUPPORTED_SWAP_RUNTIME_BLOCKS.has(current.key)\n      ? current.pendingExercises?.[0] ?? null\n      : null;''',
'''  const swapExercise = current?.pendingExercises?.[0] ?? null;\n  const needsBuilderRuntimeSync = Boolean(\n    current && isManualBuilderBlock && SUPPORTED_SWAP_RUNTIME_BLOCKS.has(current.key)\n  );'''
)
overlay = overlay.replace(
'''      await syncEnvironmentBuilderSwapRuntime({\n        sessionExerciseId: swapExercise.sessionExerciseId,\n        oldExerciseId,\n        substitute: result?.substitute ?? {},\n      });''',
'''      if (needsBuilderRuntimeSync) {\n        await syncEnvironmentBuilderSwapRuntime({\n          sessionExerciseId: swapExercise.sessionExerciseId,\n          oldExerciseId,\n          substitute: result?.substitute ?? {},\n        });\n      }'''
)
overlay = overlay.replace(
'''      <Pressable\n        onPress={() => setVisible(true)}\n        style={({ pressed }) => [styles.floatingButton, pressed && styles.pressed]}\n      >\n        <Ionicons name="ellipsis-horizontal" size={17} color={colors.textPrimary} />\n        <Text style={styles.floatingText}>OPTIONS</Text>\n      </Pressable>''',
'''      <Pressable\n        onPress={() => setVisible(true)}\n        style={({ pressed }) => [\n          variant === 'inline' ? styles.inlineButton : styles.floatingButton,\n          pressed && styles.pressed,\n        ]}\n      >\n        <Ionicons\n          name={hasSwapChoice ? 'swap-horizontal-outline' : 'ellipsis-horizontal'}\n          size={17}\n          color={colors.textPrimary}\n        />\n        <Text style={styles.floatingText}>{hasSwapChoice ? 'Adapter' : 'Options'}</Text>\n      </Pressable>'''
)
overlay = overlay.replace(
'''  floatingText: {\n    fontFamily: 'Oswald_700Bold',''',
'''  inlineButton: {\n    minHeight: 36,\n    paddingHorizontal: 11,\n    borderRadius: 11,\n    borderWidth: 1,\n    borderColor: colors.border,\n    backgroundColor: colors.surface,\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: 7,\n  },\n  floatingText: {\n    fontFamily: 'Oswald_700Bold','''
)
overlay_path.write_text(overlay, encoding='utf-8')

# Environment player: same shell/navigation/tool placement as the main focused player.
env_path = Path('app/workout/environment-session-core.js')
env = env_path.read_text(encoding='utf-8')
env = env.replace(
"import EnvironmentWodBlock from '../../src/components/workout/EnvironmentWodBlock';\n",
"import EnvironmentWodBlock from '../../src/components/workout/EnvironmentWodBlock';\nimport EnvironmentSwapOverlay from '../../src/components/workout/EnvironmentSwapOverlay';\n"
)
env = env.replace(
"import { useWorkout } from '../../src/contexts/WorkoutContext';\n",
"import { useWorkout } from '../../src/contexts/WorkoutContext';\nimport { useUgerodTheme } from '../../src/contexts/UgerodThemeContext';\n"
)

env = env.replace(
'export default function EnvironmentSessionCore({ environmentCode }) {\n  const { workout, updateWorkout } = useWorkout();',
'''export default function EnvironmentSessionCore({\n  environmentCode,\n  onOpenOverview,\n  onOpenPlanB,\n  onOpenWhy,\n  onOpenAdjust,\n  showPlanB = false,\n}) {\n  const { workout, updateWorkout } = useWorkout();\n  const { colors: themeColors, isDark } = useUgerodTheme();\n  const shellStyles = useMemo(\n    () => createShellStyles(themeColors, isDark),\n    [themeColors, isDark]\n  );'''
)

old_header = '''    <SafeAreaView style={styles.screen}>\n      <View style={styles.header}>\n        <Pressable onPress={() => router.back()} hitSlop={12} style={styles.iconButton}>\n          <Ionicons name="arrow-back" size={21} color={colors.textPrimary} />\n        </Pressable>\n        <View style={styles.headerCopy}>\n          <Text style={styles.eyebrow}>{environmentCode === 'GYM' ? 'SALLE' : 'EXTÉRIEUR'}</Text>\n          <Text style={styles.headerTitle}>{blockTitle(currentBlock, currentKey.toUpperCase())}</Text>\n        </View>\n        <Text style={styles.stepText}>{currentIndex + 1}/{blocks.length}</Text>\n      </View>\n\n      <View style={styles.progressTrack}>\n        <View style={[styles.progressFill, { width: `${((currentIndex + 1) / blocks.length) * 100}%` }]} />\n      </View>\n\n      <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>'''
new_header = '''    <SafeAreaView style={[styles.screen, { backgroundColor: themeColors.background }]}>\n      <View style={shellStyles.header}>\n        <View style={shellStyles.headerTop}>\n          <Pressable\n            onPress={() => router.replace('/workout/preparation')}\n            hitSlop={12}\n            style={shellStyles.iconButton}\n          >\n            <Ionicons name="arrow-back" size={21} color={themeColors.text} />\n          </Pressable>\n\n          <View style={shellStyles.headerCopy}>\n            <Text style={shellStyles.headerEyebrow}>\n              {(environmentCode === 'GYM' ? 'SALLE' : environmentCode === 'OUTDOOR' ? 'EXTÉRIEUR' : environmentCode)} · Bloc {currentIndex + 1}/{blocks.length}\n            </Text>\n            <Text style={shellStyles.headerTitle}>\n              {blockTitle(currentBlock, currentKey.toUpperCase())}\n            </Text>\n            <Text numberOfLines={1} style={shellStyles.headerMeta}>\n              {[\n                currentBlock?.structure ?? currentBlock?.execution_style?.label_fr ?? null,\n                Number(currentBlock?.duration_minutes ?? currentBlock?.durationMinutes) > 0\n                  ? `${Number(currentBlock?.duration_minutes ?? currentBlock?.durationMinutes)} min`\n                  : null,\n              ].filter(Boolean).join(' · ')}\n            </Text>\n          </View>\n\n          {typeof onOpenOverview === 'function' ? (\n            <Pressable\n              onPress={onOpenOverview}\n              accessibilityRole="button"\n              accessibilityLabel="Voir ma séance"\n              style={shellStyles.overviewButton}\n            >\n              <Ionicons name="clipboard-outline" size={17} color={themeColors.text} />\n              <Text style={shellStyles.overviewButtonText}>Ma séance</Text>\n            </Pressable>\n          ) : null}\n        </View>\n\n        <View style={shellStyles.coachTools}>\n          {typeof onOpenWhy === 'function' ? (\n            <Pressable onPress={onOpenWhy} style={shellStyles.coachTool}>\n              <Ionicons name="help-circle-outline" size={17} color={themeColors.textSecondary} />\n              <Text style={shellStyles.coachToolText}>Pourquoi ?</Text>\n            </Pressable>\n          ) : null}\n          {typeof onOpenAdjust === 'function' ? (\n            <Pressable onPress={onOpenAdjust} style={shellStyles.coachTool}>\n              <Ionicons name="options-outline" size={17} color={themeColors.accent} />\n              <Text style={shellStyles.coachToolText}>Ajuster</Text>\n            </Pressable>\n          ) : null}\n          {showPlanB && typeof onOpenPlanB === 'function' ? (\n            <Pressable onPress={onOpenPlanB} style={shellStyles.coachTool}>\n              <Ionicons name="shuffle-outline" size={17} color={themeColors.secondaryAccent} />\n              <Text style={shellStyles.coachToolText}>Plan B</Text>\n            </Pressable>\n          ) : null}\n          <EnvironmentSwapOverlay variant="inline" />\n        </View>\n      </View>\n\n      <View style={shellStyles.progressTrack}>\n        <View\n          style={[\n            shellStyles.progressFill,\n            { width: `${blocks.length > 0 ? Math.round((currentIndex / blocks.length) * 100) : 0}%` },\n          ]}\n        />\n      </View>\n\n      <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>'''
if old_header not in env:
    raise SystemExit('environment header block not found')
env = env.replace(old_header, new_header, 1)

# Make the simple environment block read like the focused HOME player: one exercise at a time,
# no duplicated giant block title, with a clear next/finish CTA.
start = env.index('function SimpleBlock({ block, exercises, onComplete }) {')
end = env.index('\nfunction StrengthBlock(', start)
new_simple = '''function SimpleBlock({ block, exercises, onComplete }) {\n  const { colors: themeColors, isDark } = useUgerodTheme();\n  const focusedStyles = useMemo(\n    () => createEnvironmentFocusedStyles(themeColors, isDark),\n    [themeColors, isDark]\n  );\n  const [exerciseIndex, setExerciseIndex] = useState(0);\n  const exercise = exercises[exerciseIndex] ?? exercises[0] ?? null;\n\n  if (!exercise) {\n    return (\n      <View style={focusedStyles.exerciseCard}>\n        <Text style={focusedStyles.exerciseName}>Bloc vide</Text>\n        <Text style={focusedStyles.exercisePrescription}>Aucun exercice exécutable n’a été reçu.</Text>\n      </View>\n    );\n  }\n\n  const isLast = exerciseIndex >= exercises.length - 1;\n\n  function next() {\n    if (isLast) {\n      onComplete();\n      return;\n    }\n    setExerciseIndex((current) => Math.min(exercises.length - 1, current + 1));\n  }\n\n  return (\n    <>\n      <View style={focusedStyles.mediaCard}>\n        <View style={focusedStyles.mediaFallback}>\n          <View style={focusedStyles.mediaFallbackIcon}>\n            <Ionicons name="barbell-outline" size={34} color={themeColors.accent} />\n          </View>\n          <Text style={focusedStyles.mediaFallbackText}>{blockTitle(block)}</Text>\n        </View>\n        <View style={focusedStyles.mediaOverlayTop}>\n          <Text style={focusedStyles.exercisePosition}>\n            Exercice {exerciseIndex + 1} / {exercises.length}\n          </Text>\n        </View>\n      </View>\n\n      <View style={focusedStyles.exerciseCard}>\n        <Text style={focusedStyles.exerciseName}>{exercise.name}</Text>\n        {exercise.prescription ? (\n          <Text style={focusedStyles.exercisePrescription}>{exercise.prescription}</Text>\n        ) : null}\n      </View>\n\n      {exercises.length > 1 ? (\n        <View style={focusedStyles.exerciseNav}>\n          <Pressable\n            onPress={() => setExerciseIndex((current) => Math.max(0, current - 1))}\n            disabled={exerciseIndex === 0}\n            style={[focusedStyles.navButton, exerciseIndex === 0 && focusedStyles.actionDisabled]}\n          >\n            <Ionicons name="chevron-back" size={20} color={themeColors.text} />\n          </Pressable>\n          <View style={focusedStyles.navDots}>\n            {exercises.map((row, index) => (\n              <View\n                key={exerciseKey(row) ?? `${index}`}\n                style={[focusedStyles.navDot, index === exerciseIndex && focusedStyles.navDotActive]}\n              />\n            ))}\n          </View>\n          <Pressable\n            onPress={() => setExerciseIndex((current) => Math.min(exercises.length - 1, current + 1))}\n            disabled={isLast}\n            style={[focusedStyles.navButton, isLast && focusedStyles.actionDisabled]}\n          >\n            <Ionicons name="chevron-forward" size={20} color={themeColors.text} />\n          </Pressable>\n        </View>\n      ) : null}\n\n      <Pressable onPress={next} style={focusedStyles.primaryButtonLarge}>\n        <Ionicons name="checkmark-circle-outline" size={20} color={themeColors.textOnAccent} />\n        <Text style={focusedStyles.primaryButtonTextLarge}>\n          {isLast ? 'Réalisé · terminer le bloc' : 'Réalisé · suivant'}\n        </Text>\n      </Pressable>\n    </>\n  );\n}\n'''
env = env[:start] + new_simple + env[end:]

# Append shell/focused styles before the existing legacy style sheet.
marker = '\nconst styles = StyleSheet.create({'
if marker not in env:
    raise SystemExit('environment styles marker not found')
extra_styles = '''\nfunction createShellStyles(colors, isDark) {\n  return StyleSheet.create({\n    header: {\n      paddingHorizontal: spacing.lg,\n      paddingTop: 8,\n      paddingBottom: 10,\n      backgroundColor: colors.background,\n    },\n    headerTop: {\n      minHeight: 64,\n      flexDirection: 'row',\n      alignItems: 'center',\n      gap: 12,\n    },\n    iconButton: {\n      width: 42,\n      height: 42,\n      borderRadius: 14,\n      alignItems: 'center',\n      justifyContent: 'center',\n      backgroundColor: colors.surfaceElevated,\n      borderWidth: 1,\n      borderColor: colors.border,\n    },\n    headerCopy: { flex: 1, minWidth: 0 },\n    headerEyebrow: {\n      fontFamily: 'Manrope_700Bold',\n      fontSize: 9,\n      letterSpacing: 0.7,\n      textTransform: 'uppercase',\n      color: colors.accent,\n    },\n    headerTitle: {\n      marginTop: 2,\n      fontFamily: 'Manrope_800ExtraBold',\n      fontSize: 22,\n      lineHeight: 27,\n      color: colors.text,\n    },\n    headerMeta: {\n      marginTop: 2,\n      fontFamily: 'Manrope_500Medium',\n      fontSize: 10,\n      lineHeight: 14,\n      color: colors.textSecondary,\n    },\n    overviewButton: {\n      minHeight: 38,\n      paddingHorizontal: 10,\n      borderRadius: 12,\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surfaceElevated,\n      flexDirection: 'row',\n      alignItems: 'center',\n      gap: 6,\n    },\n    overviewButtonText: {\n      fontFamily: 'Manrope_700Bold',\n      fontSize: 10,\n      color: colors.text,\n    },\n    coachTools: {\n      marginTop: 8,\n      flexDirection: 'row',\n      flexWrap: 'wrap',\n      gap: 8,\n    },\n    coachTool: {\n      minHeight: 36,\n      paddingHorizontal: 11,\n      borderRadius: 11,\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surface,\n      flexDirection: 'row',\n      alignItems: 'center',\n      justifyContent: 'center',\n      gap: 6,\n    },\n    coachToolText: {\n      fontFamily: 'Manrope_700Bold',\n      fontSize: 10,\n      color: colors.text,\n    },\n    progressTrack: { height: 3, backgroundColor: colors.border },\n    progressFill: { height: 3, backgroundColor: colors.accent },\n  });\n}\n\nfunction createEnvironmentFocusedStyles(colors, isDark) {\n  return StyleSheet.create({\n    mediaCard: {\n      minHeight: 190,\n      borderRadius: 18,\n      overflow: 'hidden',\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surface,\n    },\n    mediaFallback: {\n      flex: 1,\n      minHeight: 190,\n      alignItems: 'center',\n      justifyContent: 'center',\n      gap: 10,\n      backgroundColor: colors.surface,\n    },\n    mediaFallbackIcon: {\n      width: 64,\n      height: 64,\n      borderRadius: 22,\n      alignItems: 'center',\n      justifyContent: 'center',\n      backgroundColor: colors.accentSoft,\n    },\n    mediaFallbackText: {\n      fontFamily: 'Manrope_800ExtraBold',\n      fontSize: 16,\n      color: colors.textSecondary,\n    },\n    mediaOverlayTop: {\n      position: 'absolute',\n      top: 12,\n      right: 12,\n      paddingHorizontal: 10,\n      paddingVertical: 6,\n      borderRadius: 999,\n      backgroundColor: isDark ? 'rgba(0,0,0,0.58)' : 'rgba(255,255,255,0.88)',\n    },\n    exercisePosition: {\n      fontFamily: 'Manrope_700Bold',\n      fontSize: 9,\n      color: colors.text,\n    },\n    exerciseCard: {\n      marginTop: 12,\n      padding: 18,\n      borderRadius: 18,\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surfaceElevated,\n    },\n    exerciseName: {\n      fontFamily: 'Manrope_800ExtraBold',\n      fontSize: 20,\n      lineHeight: 25,\n      color: colors.text,\n    },\n    exercisePrescription: {\n      marginTop: 6,\n      fontFamily: 'Manrope_500Medium',\n      fontSize: 13,\n      lineHeight: 19,\n      color: colors.textSecondary,\n    },\n    exerciseNav: {\n      marginTop: 12,\n      minHeight: 42,\n      flexDirection: 'row',\n      alignItems: 'center',\n      justifyContent: 'space-between',\n      gap: 12,\n    },\n    navButton: {\n      width: 42,\n      height: 42,\n      borderRadius: 13,\n      alignItems: 'center',\n      justifyContent: 'center',\n      borderWidth: 1,\n      borderColor: colors.border,\n      backgroundColor: colors.surface,\n    },\n    navDots: { flex: 1, flexDirection: 'row', justifyContent: 'center', gap: 7 },\n    navDot: { width: 7, height: 7, borderRadius: 4, backgroundColor: colors.borderStrong },\n    navDotActive: { width: 20, backgroundColor: colors.accent },\n    actionDisabled: { opacity: 0.35 },\n    primaryButtonLarge: {\n      minHeight: 54,\n      marginTop: 14,\n      paddingHorizontal: 18,\n      borderRadius: 16,\n      alignItems: 'center',\n      justifyContent: 'center',\n      flexDirection: 'row',\n      gap: 8,\n      backgroundColor: colors.accent,\n    },\n    primaryButtonTextLarge: {\n      fontFamily: 'Manrope_800ExtraBold',\n      fontSize: 12,\n      color: colors.textOnAccent,\n    },\n  });\n}\n'''
env = env.replace(marker, extra_styles + marker, 1)
env_path.write_text(env, encoding='utf-8')

# Canonical environment WOD uses the same V3 UI renderer as HOME/BOX. Environment-specific timed/run
# protocols remain in EnvironmentSessionCore and are not mechanically changed.
wod_path = Path('src/components/workout/EnvironmentWodBlock.js')
wod = wod_path.read_text(encoding='utf-8')
wod = wod.replace("import { colors } from '../../constants';\nimport WodProtocolPlayer from './WodProtocolPlayer';", "import { useMemo } from 'react';\nimport { useUgerodTheme } from '../../contexts/UgerodThemeContext';\nimport WodProtocolPlayer from './WodProtocolPlayerV3';")
wod = wod.replace(
'''export default function EnvironmentWodBlock({\n  block,''',
'''export default function EnvironmentWodBlock({\n  block,'''
)
wod = wod.replace(
'''}) {\n  const durationMinutes = Math.max(''',
'''}) {\n  const { colors, isDark } = useUgerodTheme();\n  const styles = useMemo(() => createStyles(colors, isDark), [colors, isDark]);\n  const durationMinutes = Math.max(''',
1
)
wod = wod.replace("<Text style={styles.completeButtonText}>VALIDER LE WOD</Text>", "<Text style={styles.completeButtonText}>Terminer la séance</Text>")
wod = wod.replace('const styles = StyleSheet.create({', 'function createStyles(colors, isDark) {\n  return StyleSheet.create({')
wod = wod.rstrip()
if wod.endswith('});'):
    wod = wod[:-3] + '  });\n}\n'
wod = wod.replace('backgroundColor: colors.primary,', 'backgroundColor: colors.accent,')
wod = wod.replace("fontFamily: 'Oswald_700Bold',", "fontFamily: 'Manrope_800ExtraBold',")
wod = wod.replace('color: colors.brandWhite,', 'color: colors.textOnAccent,')
wod_path.write_text(wod, encoding='utf-8')
